#!/usr/bin/env bash
# Build paper/paper.pdf with a pinned Tectonic (downloaded to .tools/ with a SHA-256 check if missing).
# Numbers, tables and figures must already have been generated by `make all` (src/viz/paper_*.py).
set -euo pipefail
cd "$(dirname "$0")"
ROOT=$(cd .. && pwd)
VERSION=0.16.9
SHA256=60b13a0826ae7ad9ce34b4a2df06bff2cfcfa6dda8a915477c0cbb84e1a4a902
TECTONIC="$ROOT/.tools/tectonic"
if [ ! -x "$TECTONIC" ]; then
  mkdir -p "$ROOT/.tools"
  curl -fsSL -o "$ROOT/.tools/tectonic.tar.gz" \
    "https://github.com/tectonic-typesetting/tectonic/releases/download/tectonic%40${VERSION}/tectonic-${VERSION}-x86_64-unknown-linux-musl.tar.gz"
  echo "${SHA256}  $ROOT/.tools/tectonic.tar.gz" | sha256sum -c -
  tar -xzf "$ROOT/.tools/tectonic.tar.gz" -C "$ROOT/.tools"
fi
SOURCE_DATE_EPOCH=$(git -C "$ROOT" log -1 --format=%ct 2>/dev/null || echo 0) "$TECTONIC" --keep-logs --outdir . paper.tex
echo "built $(pwd)/paper.pdf"
